-- Seed notification_templates with the email designs that are hard-coded in the
-- send-* edge functions, so the admin Notification Center can manage them.
-- Placeholders use {{variable}} syntax rendered by notification-dispatcher;
-- {{action_url}} is always provided by the dispatcher.
--
-- Safe to re-run: new types are inserted, and existing rows only get the
-- email/push columns that are still empty, so admin edits are never overwritten.

WITH seed(type, title_template, message_template, email_subject_template, email_html_template, email_text_template, push_title_template, push_body_template, variables) AS (
  VALUES
  -- send-join-status-notification
  ('join_approved', 'Request approved!', 'Your request to join "{{trip_title}}" has been approved', 'Your join request was approved', '<!doctype html><html lang="en"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width" /><title>Ketravelan</title></head><body style="margin:0;background:#f4f6f8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Arial"><div style="display:none;font-size:1px;color:#f4f6f8;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden">Update on your join request</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="padding:32px 0;"><tr><td align="center"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:520px;background:#ffffff;border-radius:16px;border:1px solid #e5e7eb;box-shadow:0 10px 28px rgba(15,23,42,.08);"><tr><td align="center" style="padding:24px 20px"><img src="https://ketravelan.com/ketravelan_logo.png" alt="Ketravelan" style="display:block;border:0;outline:none;text-decoration:none;height:28px;width:auto" /></td></tr><tr><td style="height:1px;background:#e5e7eb" aria-hidden="true"></td></tr><tr><td style="padding:28px"><h1 style="font-size:20px;font-weight:700;margin:0 0 8px;color:#020617;text-align:center">Your join request was approved</h1><div style="font-size:15px;line-height:1.65;color:#475569;margin-bottom:24px;text-align:center">Great news! You''ve been approved to join <strong>{{trip_title}}</strong> ({{trip_destination}}).</div><table role="presentation" cellspacing="0" cellpadding="0" width="100%"><tr><td align="center"><a href="{{action_url}}" target="_blank" style="display:inline-block;padding:14px 26px;border-radius:10px;background:#000000;color:#ffffff;text-decoration:none;font-weight:600">View Trip</a></td></tr></table></td></tr><tr><td style="padding:24px 28px;font-size:12px;color:#64748b;line-height:1.6">You’re receiving this because you requested to join a trip on Ketravelan.<br><br>If the button 