filled AS (
  UPDATE public.notification_templates t
  SET
    email_subject_template = COALESCE(NULLIF(t.email_subject_template, ''), s.email_subject_template),
    email_html_template    = COALESCE(NULLIF(t.email_html_template, ''), s.email_html_template),
    email_text_template    = COALESCE(NULLIF(t.email_text_template, ''), s.email_text_template),
    push_title_template    = COALESCE(NULLIF(t.push_title_template, ''), s.push_title_template),
    push_body_template     = COALESCE(NULLIF(t.push_body_template, ''), s.push_body_template),
    variables = CASE WHEN t.variables IS NULL OR t.variables = '[]'::jsonb THEN s.variables ELSE t.variables END
  FROM seed s
  WHERE t.type = s.type
  RETURNING t.type
)
INSERT INTO public.notification_templates
  (type, title_template, message_template, email_subject_template, email_html_template, email_text_template, push_title_template, push_body_template, variables, channels, is_active)
SELECT s.type, s.title_template, s.message_template, s.email_subject_template, s.email_html_template, s.email_text_template, s.push_title_template, s.push_body_template, s.variables,
       ARRAY['in_app', 'push', 'email']::text[], true
FROM seed s
WHERE NOT EXISTS (SELECT 1 FROM public.notification_templates t WHERE t.type = s.type);
